//! Light and dark Dock icons on macOS.
//!
//! The bundled `icon-dark.icns` is the dark startup icon, so a dark macOS
//! appearance does not flash the light variant before the app is ready.
//! While the app runs, the Dock tile follows the user's macOS theme (Dark Mode
//! or macOS 26+ `AppleIconAppearanceTheme`): the dark icon when dark, the light
//! one otherwise. Both PNGs are generated by `scripts/make-icons.sh`. Elsewhere
//! this is a no-op.

use tauri::Theme;

/// Resolves which Dock icon variant to show given the system Light/Dark
/// appearance and macOS 26+'s optional `AppleIconAppearanceTheme` setting.
fn resolve_theme(system_theme: Theme, icon_appearance: Option<&str>) -> Theme {
    match icon_appearance {
        Some(value) if value.ends_with("Dark") => Theme::Dark,
        Some(value) if value.ends_with("Light") => Theme::Light,
        _ => system_theme,
    }
}

#[cfg(target_os = "macos")]
mod macos {
    use std::sync::atomic::{AtomicU8, Ordering};

    use objc2::{AllocAnyThread, MainThreadMarker};
    use objc2_app_kit::{NSAppearanceNameAqua, NSAppearanceNameDarkAqua, NSApplication, NSImage};
    use objc2_foundation::{NSArray, NSData, NSUserDefaults, ns_string};
    use tauri::Theme;

    const UNSET: u8 = 0;
    const LIGHT: u8 = 1;
    const DARK: u8 = 2;

    static APPLIED: AtomicU8 = AtomicU8::new(UNSET);

    pub(super) static LIGHT_BYTES: &[u8] = include_bytes!("../icons/dock-light.png");
    pub(super) static DARK_BYTES: &[u8] = include_bytes!("../icons/dock-dark.png");

    fn encode(theme: Theme) -> u8 {
        match theme {
            Theme::Dark => DARK,
            _ => LIGHT,
        }
    }

    fn effective_system_theme(mtm: MainThreadMarker) -> Theme {
        let app = NSApplication::sharedApplication(mtm);
        let appearance = app.effectiveAppearance();
        let names = unsafe { NSArray::from_slice(&[NSAppearanceNameAqua, NSAppearanceNameDarkAqua]) };
        let is_dark = appearance
            .bestMatchFromAppearancesWithNames(&names)
            .is_some_and(|name| unsafe { &*name == NSAppearanceNameDarkAqua });
        if is_dark {
            Theme::Dark
        } else {
            Theme::Light
        }
    }

    fn icon_appearance_default() -> Option<String> {
        NSUserDefaults::standardUserDefaults()
            .stringForKey(ns_string!("AppleIconAppearanceTheme"))
            .map(|s| s.to_string())
    }

    pub(super) fn decode_icon(bytes: &[u8]) -> Option<objc2::rc::Retained<NSImage>> {
        let data = NSData::with_bytes(bytes);
        NSImage::initWithData(NSImage::alloc(), &data)
    }

    pub(super) fn apply(hint: Option<Theme>, force: bool) {
        // AppKit requires Dock icon updates on the main thread; anything else skips.
        let Some(mtm) = MainThreadMarker::new() else {
            return;
        };

        let system_theme = hint.unwrap_or_else(|| effective_system_theme(mtm));
        let resolved = super::resolve_theme(system_theme, icon_appearance_default().as_deref());
        let code = encode(resolved);
        if !force && APPLIED.load(Ordering::Relaxed) == code {
            return;
        }

        let bytes = if resolved == Theme::Dark {
            DARK_BYTES
        } else {
            LIGHT_BYTES
        };
        let Some(image) = decode_icon(bytes) else {
            return;
        };
        let app = NSApplication::sharedApplication(mtm);
        #[allow(unused_unsafe)]
        unsafe {
            app.setApplicationIconImage(Some(&image));
        }
        APPLIED.store(code, Ordering::Relaxed);
    }
}

/// Applies the Dock icon unconditionally, reading the current system theme when
/// `hint` is `None`. Use this on `RunEvent::Ready`, after Tauri's dev-mode
/// icon setup has run.
pub fn refresh(hint: Option<Theme>) {
    #[cfg(target_os = "macos")]
    macos::apply(hint, true);
    #[cfg(not(target_os = "macos"))]
    let _ = hint;
}

/// Updates the Dock icon if the resolved theme differs from the last applied
/// icon.
pub fn sync(hint: Option<Theme>) {
    #[cfg(target_os = "macos")]
    macos::apply(hint, false);
    #[cfg(not(target_os = "macos"))]
    let _ = hint;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn resolve_theme_respects_icon_appearance_and_falls_back_to_system() {
        assert_eq!(resolve_theme(Theme::Dark, None), Theme::Dark);
        assert_eq!(resolve_theme(Theme::Light, None), Theme::Light);
        assert_eq!(
            resolve_theme(Theme::Dark, Some("RegularAutomatic")),
            Theme::Dark
        );
        assert_eq!(
            resolve_theme(Theme::Light, Some("RegularAutomatic")),
            Theme::Light
        );
        assert_eq!(
            resolve_theme(Theme::Light, Some("RegularDark")),
            Theme::Dark
        );
        assert_eq!(
            resolve_theme(Theme::Light, Some("ClearDark")),
            Theme::Dark
        );
        assert_eq!(
            resolve_theme(Theme::Dark, Some("RegularLight")),
            Theme::Light
        );
        assert_eq!(
            resolve_theme(Theme::Dark, Some("TintedLight")),
            Theme::Light
        );
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn dock_icons_decode_and_differ() {
        assert_ne!(macos::LIGHT_BYTES, macos::DARK_BYTES);
        assert!(macos::decode_icon(macos::LIGHT_BYTES).is_some());
        assert!(macos::decode_icon(macos::DARK_BYTES).is_some());
    }
}
